#!/usr/bin/env node
// scripts/verify-build-output.cjs
// Asserts that the post-build artifacts actually carry the transforms they should.
//
// Run after `napi build --pipe "node scripts/apply-glue.cjs"`. Exits non-zero with a
// specific message when an expected transform is missing, so a regression in the pipe
// fails CI instead of reaching a published artifact.
//
// This asserts the *presence of specific transforms*, not that the generated file matches
// a committed copy — a napi version bump would otherwise turn every release into a diff
// to review, which is the restated-inventory problem this check exists to avoid.

const fs = require('fs')

const NATIVE_DTS = 'native.d.ts'
const INDEX_JS = 'index.js'

const failures = []

function expectFile(file, what) {
  if (!fs.existsSync(file)) {
    failures.push(`${file} does not exist — was the native addon built? (${what})`)
    return null
  }
  return fs.readFileSync(file, 'utf8')
}

// --- Generated type declarations: the pipe's transform must have run -----------------
const dts = expectFile(NATIVE_DTS, 'generated by --dts native.d.ts')

if (dts !== null) {
  // Discriminated union replaces the flat interface napi emits by default.
  if (dts.includes('export type CellValue =')) {
    // present
  } else {
    failures.push(
      `${NATIVE_DTS} is missing the CellValue discriminated union ` +
        `("export type CellValue ="). The --pipe transform did not run.`
    )
  }

  if (dts.includes('export interface CellValue {')) {
    failures.push(
      `${NATIVE_DTS} still contains the flat "export interface CellValue {" — ` +
        `the union transform did not replace it.`
    )
  }

  if (dts.includes('export type CellValueInput =')) {
    // present
  } else {
    failures.push(
      `${NATIVE_DTS} is missing "export type CellValueInput =" — the --pipe transform did not run.`
    )
  }

  // Refined Cell setter: napi emits `set value(val: unknown)`, the pipe narrows it.
  if (dts.includes('set value(val: unknown)')) {
    failures.push(
      `${NATIVE_DTS} still types the Cell value setter as unknown — ` +
        `the class-body refinement did not run.`
    )
  }
  if (!dts.includes('set value(val: CellValueInput')) {
    failures.push(
      `${NATIVE_DTS} is missing the refined Cell value setter ` +
        `("set value(val: CellValueInput"). The --pipe transform did not run.`
    )
  }

  // getCell overload declarations, injected by the pipe into the napi-generated classes.
  for (const [label, needle] of [
    ['Worksheet.getCell(address: string)', 'getCell(address: string): Cell'],
    ['Worksheet.getCell(row, col)', 'getCell(row: number, col: number): Cell'],
    ['Row.getCell(col: number)', 'getCell(col: number): Cell'],
    ['Row.getCell(col: string)', 'getCell(col: string): Cell'],
  ]) {
    if (!dts.includes(needle)) {
      failures.push(`${NATIVE_DTS} is missing the ${label} overload declaration.`)
    }
  }
}

// --- Published entrypoint: hand-maintained, must still carry the runtime glue ---------
const indexJs = expectFile(INDEX_JS, 'checked-in package entrypoint')

if (indexJs !== null) {
  if (!indexJs.includes('__EXCELJS_GETCELL_GLUE__')) {
    failures.push(
      `${INDEX_JS} no longer carries the __EXCELJS_GETCELL_GLUE__ marker. ` +
        `This file is hand-maintained; the build does not regenerate it.`
    )
  }
  for (const [label, needle] of [
    ['Worksheet.prototype.getCell', 'nativeBinding.Worksheet.prototype.getCell'],
    ['Row.prototype.getCell', 'nativeBinding.Row.prototype.getCell'],
  ]) {
    if (!indexJs.includes(needle)) {
      failures.push(`${INDEX_JS} is missing the ${label} overload glue.`)
    }
  }
}

if (failures.length > 0) {
  console.error('[verify-build-output] FAILED\n')
  for (const f of failures) console.error(`  - ${f}`)
  console.error('')
  process.exit(1)
}

console.log('[verify-build-output] OK — pipe transforms present, entrypoint glue intact')
